import { useState } from "react";
import Calculation from "../Calculation/Calculation";

import "./Appear.css";

function Appear() {
  let buttonArr = ["Calculation", "Data"];
  const [appear, setAppear] = useState(false);
  function showHide() {
    setAppear(!appear);
    console.log(appear);

  }
  function whichAppear(value) {
    switch (value) {
      case "Calculation":
        return <Calculation />;
        break;
      case "Data":
        return <p>jjj</p>;
        break;
    }

  }

  return (
    <div className="mainAppear">
      <div className="buttons">
        {buttonArr.map((elm) => (
          <button className="forAppear" onClick={showHide}>
            {elm}
          </button>
        // {appear && whichAppear(elm)}
        ))}
      </div>
    </div>
  );
}

export default Appear;
